package presentation.snippets.poop

import io.ktor.http.HttpStatusCode
import io.ktor.server.auth.AuthenticationRole
import io.ktor.server.auth.AuthenticationScheme
import io.ktor.server.auth.AuthenticationSchemeWithRoles
import io.ktor.server.auth.authenticateWith
import io.ktor.server.auth.jwt.jwt
import io.ktor.server.auth.principal
import io.ktor.server.auth.withRoles
import io.ktor.server.routing.Route
import opensavvy.spine.api.RootResource
import opensavvy.spine.api.StaticResource
import opensavvy.spine.server.route
import opensavvy.spine.server.respond
import presentation.support.User

data class CreateUser(val name: String)

object UserAlreadyExists

object InvalidUser {
  val errors: List<String> = ["username too short", "email doesn't contain @"]
}

object Api : RootResource("api") {                   // api
  object Users : StaticResource<Api>("users", Api) { // api/users
    val list by get()                                // GET /v3/users
      .response<List<User>>()

    val create by post()                             // POST /api/users
      .request<CreateUser>()
      .response<User>()
      .failure<UserAlreadyExists>(HttpStatusCode.Conflict)
      .failure<InvalidUser>(HttpStatusCode.UnprocessableEntity)
  }
}


enum class JwtRole : AuthenticationRole {
  User, Admin;
}

data class JwtUser(val id: String, val roles: Set<JwtRole>)

fun getAllUsers(): List<User> = listOf()

val jwt: AuthenticationSchemeWithRoles<JwtUser, JwtRole, Unit, AuthenticationScheme<JwtUser, Unit>> =
  jwt<JwtUser>("ktor-arrow-server") { }
    .withRoles { it.roles }

fun Route.users() {
  authenticateWith(jwt, roles = setOf(JwtRole.Admin)) {
    route(Api.Users.list) {
      val user = call.principal
      val users = getAllUsers()
      respond(users)
    }
  }
}
